local TelescopeMaker = {}
local PRODUCTS = {
    brass_telescope = { name = "Medeninast daljnogled", brassCost = 2, glassCost = 1, woodCost = 1, time = 5, cost = 90, magnification = 30, prestige = 4, description = "Medeninast daljnogled za opazovanje." },
    silver_telescope = { name = "Srebrn daljnogled", silverCost = 2, glassCost = 1, woodCost = 1, time = 7, cost = 220, magnification = 50, prestige = 8, happiness = 1, description = "Srebrn daljnogled za astronome." },
    engraved_telescope = { name = "Vgraviran daljnogled", silverCost = 2, glassCost = 1, goldCost = 1, time = 10, cost = 500, magnification = 70, prestige = 14, happiness = 2, description = "Vgraviran daljnogled za učenjake." },
    silver_tripod_telescope = { name = "Srebrno trinožni daljnogled", silverCost = 2, goldCost = 1, glassCost = 1, brassCost = 1, time = 13, cost = 1000, magnification = 85, prestige = 22, happiness = 4, description = "Daljnogled s srebrnim stativom za plemiče." },
    gold_cased_telescope = { name = "Zlatokondični daljnogled", goldCost = 2, silverCost = 1, glassCost = 1, jewelCost = 1, time = 16, cost = 2000, magnification = 95, prestige = 35, happiness = 7, description = "Daljnogled z zlatim ohišjem za visoke plemiče." },
    royal_grand_telescope = { name = "Kraljevski veliki daljnogled", goldCost = 3, silverCost = 2, jewelCost = 2, pearlCost = 1, glassCost = 2, time = 22, cost = 4000, magnification = 100, prestige = 62, happiness = 13, description = "Veliki kraljevski daljnogled z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Teleskopska delavnica", cost = { gold = 350, wood = 140, stone = 250 }, upkeep = 9, qualityBonus = 5 },
    lens_room = { name = "Lečna soba", cost = { gold = 1200, wood = 280, stone = 500, glass = 8 }, upkeep = 30, qualityBonus = 18 },
    polishing_room = { name = "Polirnica", cost = { gold = 2800, wood = 400, stone = 800, silver = 40, steel = 8 }, upkeep = 70, qualityBonus = 30 },
    royal_telescope_atelier = { name = "Kraljevski atelje daljnogledov", cost = { gold = 12000, wood = 600, stone = 1200, gold = 80, jewel = 25 }, upkeep = 240, qualityBonus = 55, prestigeBonus = 50 },
}
TelescopeMaker.brassStock = 14; TelescopeMaker.glassStock = 12; TelescopeMaker.woodStock = 14; TelescopeMaker.silverStock = 8; TelescopeMaker.goldStock = 6; TelescopeMaker.jewelStock = 6; TelescopeMaker.pearlStock = 4
TelescopeMaker.productStock = {}; TelescopeMaker.buildings = {}; TelescopeMaker.maker = nil; TelescopeMaker.activeMaking = {}; TelescopeMaker.totalProducts = 0; TelescopeMaker.dayTimer = 0
function TelescopeMaker.init() TelescopeMaker.brassStock=14; TelescopeMaker.glassStock=12; TelescopeMaker.woodStock=14; TelescopeMaker.silverStock=8; TelescopeMaker.goldStock=6; TelescopeMaker.jewelStock=6; TelescopeMaker.pearlStock=4; TelescopeMaker.productStock={}; TelescopeMaker.buildings={}; TelescopeMaker.maker=nil; TelescopeMaker.activeMaking={}; TelescopeMaker.totalProducts=0; TelescopeMaker.dayTimer=0; print("[TelescopeMaker] Royal Telescope Maker System initialized (6 products, 4 buildings)") end
function TelescopeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TelescopeMaker.maker={name=n or ("Teleskopar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Teleskopar najet: %s (spretnost: %d)",TelescopeMaker.maker.name,s),"success") end; return true end
function TelescopeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TelescopeMaker.build(id) local ok,e=TelescopeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TelescopeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TelescopeMaker.getQualityBonus() local b=0; for _,bd in ipairs(TelescopeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TelescopeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.brassCost and TelescopeMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.glassCost and TelescopeMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.woodCost and TelescopeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and TelescopeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TelescopeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TelescopeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TelescopeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TelescopeMaker.buildings==0 then return false,"Potrebna delavnica" end; if not TelescopeMaker.maker then return false,"Potreben teleskopar" end; return true end
function TelescopeMaker.make(pt,qty) qty=qty or 1; local ok,e=TelescopeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.brassCost then TelescopeMaker.brassStock=TelescopeMaker.brassStock-d.brassCost*qty end; if d.glassCost then TelescopeMaker.glassStock=TelescopeMaker.glassStock-d.glassCost*qty end; if d.woodCost then TelescopeMaker.woodStock=TelescopeMaker.woodStock-d.woodCost*qty end; if d.silverCost then TelescopeMaker.silverStock=TelescopeMaker.silverStock-d.silverCost*qty end; if d.goldCost then TelescopeMaker.goldStock=TelescopeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TelescopeMaker.jewelStock=TelescopeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TelescopeMaker.pearlStock=TelescopeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TelescopeMaker.maker then t=math.max(1,t-math.floor(TelescopeMaker.maker.skill/12)) end; table.insert(TelescopeMaker.activeMaking,{id="telescope_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,magnification=d.magnification or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TelescopeMaker.completeMaking(m) local q=1.0+(TelescopeMaker.getQualityBonus()/100); if TelescopeMaker.maker then q=q+(TelescopeMaker.maker.skill/150) end; q=math.min(2.5,q); TelescopeMaker.productStock[m.productType]=(TelescopeMaker.productStock[m.productType] or 0)+m.quantity; TelescopeMaker.totalProducts=TelescopeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TelescopeMaker.maker then TelescopeMaker.maker.itemsMade=TelescopeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TelescopeMaker.maker.skill=math.min(100,TelescopeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Daljnogled izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"telescope.completed",{productName=m.productName,magnification=m.magnification,prestige=m.prestige,happiness=m.happiness}) end end
function TelescopeMaker.update(dt) if not _G.state then return end; TelescopeMaker.dayTimer=TelescopeMaker.dayTimer+dt; if TelescopeMaker.dayTimer>=30 then TelescopeMaker.dayTimer=0; for i=#TelescopeMaker.activeMaking,1,-1 do local m=TelescopeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TelescopeMaker.completeMaking(m); table.remove(TelescopeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TelescopeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TelescopeMaker.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TelescopeMaker.getStats() return {brassStock=TelescopeMaker.brassStock,glassStock=TelescopeMaker.glassStock,woodStock=TelescopeMaker.woodStock,silverStock=TelescopeMaker.silverStock,goldStock=TelescopeMaker.goldStock,jewelStock=TelescopeMaker.jewelStock,pearlStock=TelescopeMaker.pearlStock,productStock=TelescopeMaker.productStock,numBuildings=#TelescopeMaker.buildings,hasMaker=TelescopeMaker.maker~=nil,makerName=TelescopeMaker.maker and TelescopeMaker.maker.name or "—",makerSkill=TelescopeMaker.maker and TelescopeMaker.maker.skill or 0,activeMaking=#TelescopeMaker.activeMaking,totalProducts=TelescopeMaker.totalProducts} end
return TelescopeMaker
